(function(root){'use strict';if(root.NULLIS_CONFIG?.usernameRegistry===false)return;const Core=NullisRegistryCore;let running=false,statusOwner=null,status='';
async function api(path,data){const response=await fetch('/api/usernames/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin',signal:AbortSignal.timeout(15000)});let result;try{result=await response.json()}catch{throw Error('Username service is unavailable. Your encrypted profile and ownership key are saved for retry.')}if(!response.ok)throw Error(result.error||'Username registration failed.');return result}
async function registerCurrent(){if(running||!unlockedProfile||!state.address)return;running=true;const owner=state.address.toLowerCase();let opened=unlockedProfile;const alive=()=>state.address?.toLowerCase()===owner&&unlockedProfile===opened;
 statusOwner=owner;status='Registering username…';render();
 try{
  const name=Core.normalize(opened.data.username);if(opened.data.registeredName&&opened.data.registeredName!==name)throw Error('This profile already owns another username.');
  if(!opened.data.registryKey){const key=await Core.createKey();if(!alive())return;const updated=await NullisVault.update(opened,{...opened.data,registryKey:key});if(!alive())return;localStorage.setItem(VAULT_STORAGE,JSON.stringify(updated.envelope));unlockedProfile=opened=updated;profiles.set(owner,opened.data)}
  const tag=await Core.tag(name);if(!alive())return;
  const probe={tag,owner:opened.data.registryKey.publicKey,nonce:crypto.randomUUID().replace(/-/g,'').repeat(2),expires:Date.now()+60000};const proof=await Core.signClaim(opened.data.registryKey,location.origin,probe);if(!await Core.verifyClaim(location.origin,probe,proof))throw Error('Ownership key does not match this profile. Restore its backup.');if(!alive())return;
  const challenge=await api('challenge',{tag,owner:opened.data.registryKey.publicKey});if(!alive())return;
  if(challenge.registered&&!challenge.owned)throw Error('This exact username is already registered. Choose another.');
  if(!challenge.registered){if(challenge.tag!==tag||challenge.owner!==opened.data.registryKey.publicKey||challenge.domain!==location.origin||challenge.expires<=Date.now()||challenge.expires>Date.now()+120000)throw Error('Invalid registration challenge');const signature=await Core.signClaim(opened.data.registryKey,location.origin,challenge);if(!alive())return;await api('register',{...challenge,signature})}
  if(!alive())return;const updated=await NullisVault.update(opened,{...opened.data,registeredName:name});if(!alive())return;localStorage.setItem(VAULT_STORAGE,JSON.stringify(updated.envelope));unlockedProfile=opened=updated;profiles.set(owner,opened.data);status='Username registered';toast('@'+name+' is registered. Download a new encrypted backup.');
 }catch(e){if(alive()){status=e.message;toast(status)}}finally{running=false;render()}
}
async function resolve(name){const tag=await Core.tag(name);let after='',found=null;for(let page=0;page<100;page++){const snapshot=await api('snapshot'+(after?'?after='+after:''));for(const record of snapshot.records||[])if(record.tag===tag)found=record;if(!snapshot.next){if(!found)return null;if(found.domain!==location.origin||!await Core.verifyClaim(found.domain,found,found.signature))throw Error('Invalid username ownership record');return {username:Core.normalize(name),ownerKey:found.owner}}after=snapshot.next}throw Error('Directory is too large for complete lookup. Retry later.')}
const baseRender=render;render=function(){baseRender();if(unlockedProfile?.data.registeredName){$('#username').textContent='@'+unlockedProfile.data.registeredName;$('.identity p').textContent='Registered username · Robinhood Chain';$('#copy-name').disabled=false;$('#copy-name').setAttribute('aria-label','Copy username')}if(statusOwner===state.address?.toLowerCase()&&status&&!unlockedProfile?.data.registeredName)$('.identity p').textContent=status};
$('#copy-name').onclick=async()=>{const name=unlockedProfile?.data.registeredName;if(!name)return;try{await navigator.clipboard.writeText('@'+name);toast('Username copied.')}catch{toast('Your username: @'+name)}};
const baseFields=profileFields;profileFields=function(){baseFields();if(!state.address)return;$('#modal-fields').append(node('p','Usernames are case-sensitive: Alice and alice are different names. Name guessing and registry traffic visibility remain possible.','wallet-hint'));const input=$('#profile-username');if(unlockedProfile?.data.registeredName&&input){input.disabled=true;input.value=unlockedProfile.data.registeredName}if(unlockedProfile){const b=button(running?'Registering…':unlockedProfile.data.registeredName?'Verify username registration':'Register username',registerCurrent);b.disabled=running;$('#modal-fields').append(b)}};
const submit=$('#action-form').onsubmit;$('#action-form').onsubmit=async e=>{await submit(e);if(!$('#modal').open&&unlockedProfile)await registerCurrent()};
root.NullisRegistry={registerCurrent,resolve};render();
})(globalThis);
